\begin{remarks}[3.7.9]
\label{II.3.7.9}
\medskip\noindent
\begin{enumerate}
  \item[(i)] Con la notación de \sref{II.3.7.1}, y teniendo en cuenta \sref{II.3.2.10}, tenemos, para todo $n\in\bb{Z}$, un homomorfismo canónico
    \[
    \label{II.3.7.9.1}
      \theta : r_{\sh{L},\psi}^*(\sh{O}_P(n)) \to \sh{L}^{\otimes n}
    \tag{3.7.9.1}
    \]
    definido de manera general en \sref{II.3.5.6.2}.
    Vemos inmediatamente que, bajo las condiciones de \sref{II.3.7.3}, la restricción de este homomorfismo a $X_{\psi^\flat(f)}$ envía $s/f^k$ (donde $s\in S_{n+kd}$) al elemento $(\psi^\flat(s)|X_{\psi^\flat(f)})(\psi^\flat(f)|X_{\psi^\flat(f)})^{-k}$.
  \item[(ii)] Sea $\sh{F}$ un $\sh{O}_X$-módulo cuasicoherente, y supongamos que $q$ es cuasicompacto y separado, de modo que, para todo $n\geq0$, $q_*(\sh{F}\otimes\sh{L}^{\otimes n})$ es un $\sh{O}_Y$-módulo cuasicoherente \sref[I]{I.9.2.2}.
    Sea $\sh{M}'=\bigoplus_{n\geq0}\sh{F}\otimes\sh{L}^{\otimes n}$, que es un $\sh{S}'$-módulo graduado cuasicoherente, y consideremos su imagen $\sh{M}=q_*(\sh{M}')=\bigoplus_{n\geq0}q_*(\sh{F}\otimes\sh{L}^{\otimes n})$ (que es un $\sh{S}$-módulo cuasicoherente, mediante el homomorfismo $\psi^\flat$).
    Vamos a demostrar la existencia de un homomorfismo canónico de $\sh{O}_X$-módulos
    \[
    \label{II.3.7.9.2}
      \xi : r_{\sh{L},\psi}^*(\widetilde{\sh{M}}) \to \sh{F}|G(\psi).
    \tag{3.7.9.2}
    \]

    En efecto, ya hemos definido \sref{II.3.5.6.1} un homomorfismo canónico
    \[
    \label{II.3.7.9.3}
      r_{\sh{L},\psi}^*(\widetilde{\sh{M}}) \to (q^*(\sh{M})\otimes_{q^*(\sh{S})}\sh{S}')\supertilde|G(\psi)
    \tag{3.7.9.3}
    \]
    donde el miembro de la derecha se considera como un haz cuasicoherente sobre $\Proj(\sh{S}')$.
    También tenemos un homomorfismo canónico
    \[
    \label{II.3.7.9.4}
      q^*(q_*(\sh{M}'))\otimes_{q^*(\sh{S})}\sh{S}' \to \sh{M}'
    \tag{3.7.9.4}
    \]
    para todo $\sh{S}'$-módulo graduado cuasicoherente $\sh{M}'$: para todo abierto $U$ de $X$, toda sección $t'$ de $q^*(q_*(\sh{M}'_h))$ sobre $U$ y toda sección $b'$ de $\sh{S}'_k$ sobre $U$, hacemos corresponder a $t'\otimes b'$ la sección $b'\sigma(t')$ de $\sh{M}'_{h+k}$, donde $\sigma(t')$ es la sección de $\sh{M}'_h$ sobre $U$ que corresponde canónicamente \sref[0]{0.4.4.3} a $t'$.
    Obtenemos así un homomorfismo canónico
    \[
    \label{II.3.7.9.5}
      (q^*(q_*(\sh{M}'))\otimes_{q^*(\sh{S})}\sh{S}')\supertilde|G(\psi) \to \widetilde{\sh{M}}'|G(\psi)
    \tag{3.7.9.5}
    \]
    y, finalmente, puesto que $\widetilde{\sh{M}}'$ se identifica canónicamente con $\sh{F}$ \sref{II.3.2.9}[(i)], obtenemos efectivamente el homomorfismo canónico buscado.

    Bajo las condiciones de \sref{II.3.7.3}, la restricción de este homomorfismo a $X_{\psi^\flat(f)}$ actúa de la manera siguiente:
    dada una sección $t_{nd}$ de $\sh{F}\otimes\sh{L}^{\otimes nd}$ sobre $X$, si $t'_{nd}$ es la sección $t_{nd}$ considerada como sección de $q_*(\sh{F}\otimes\sh{L}^{\otimes n})$ sobre $Y$, envía el elemento $t'_{nd}/f^n$ a la sección $(t_{nd}|X_{\psi^\flat(f)})(\psi^\flat(f)|X_{\psi^\flat(f)})^{-n}$ de $\sh{F}$ sobre $X_{\psi^\flat(f)}$.
\end{enumerate}
\end{remarks}

